{
  "technical_and_design_decisions": [
    "The Receptor Java client (U1) will use Spring WebClient for HTTP communication, aligned with Spring Framework 6's reactive programming support, and will follow Spring's HTTP client error handling and retry conventions.",
    "The refactored stream/job definition repository (U2) will use a layered architecture with a dedicated repository interface layer to decouple domain logic from deployment module concerns, leveraging Spring Data for persistence abstraction.",
    "The pluggable runtime SPI (U3) will use Java's ServiceLoader mechanism for runtime implementation discovery, with a common abstract base class for all target deployment runtime implementations to ensure consistent behavior.",
    "The persistent stream repository (U4) will use a relational database (PostgreSQL) as the backing store, with schema designed to capture stream topology, deployment state, and metadata required for failure recovery.",
    "Streaming pipeline support (U6) will be built on Spring for Apache Spark (spring-spark) and Spark Structured Streaming, reusing Spring XD's existing stream DSL where possible to minimize user-facing changes.",
    "Import Options parameterization (U8) will use Spring's @ConfigurationProperties mechanism for typed property binding, with backward compatibility for the existing —args option maintained for one major release with deprecation warnings."
  ],
  "assumptions": [
    "The project uses Java 17+ as required by Spring Framework 6.0, with Maven as the standard build tool, and existing test infrastructure (JUnit 5, Spring Test, test containers) is already configured.",
    "The Receptor API specification is stable and publicly available, with no breaking changes expected during the development of the client (U1).",
    "The existing Spring XD codebase is fully accessible and has comprehensive unit/integration test coverage to support safe refactoring for U2, U3, U4, U6, and U8.",
    "Documentation for U5 and U7 will be added to the existing Spring XD official documentation, which uses AsciiDoc format and is hosted on the project's documentation site.",
    "For the pluggable runtime SPI (U3), only Cloud Foundry and on-prem Kubernetes implementations are required for this increment, with Mesos support deferred to a future release.",
    "No new production infrastructure (e.g., database provisioning, cloud environment setup) is required as part of this increment; development and testing will use local or shared test environments.",
    "The existing Sqoop job implementation's —args option behavior is well-documented and understood, allowing for safe backward compatibility implementation for U8."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Receptor Java Client Core Implementation",
      "activity_description": "Develop the Java client for the Receptor API, including HTTP communication layer using Spring WebClient, request/response DTOs, error handling, retry logic, and unit tests for core client operations, aligned with Spring Framework 6 conventions, per U1.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A2",
      "activity_name": "Receptor Client Integration with Spring XD Diego Runtime",
      "activity_description": "Integrate the developed Receptor client into Spring XD's existing Diego runtime modules, replace legacy direct API calls with the new client, and add integration tests for end-to-end Diego interaction via Receptor, per U1.",
      "most_likely_effort": 16
    },
    {
      "activity_id": "A3",
      "activity_name": "Stream/Job Definition Repository Refactoring",
      "activity_description": "Refactor the existing stream and job definition repository code to separate domain model logic from deployment module concerns, introduce a dedicated repository interface layer, update all dependent modules to use the new interface, and add regression tests to ensure no breaking changes, per U2.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A4",
      "activity_name": "Pluggable Runtime SPI Core Design and Implementation",
      "activity_description": "Define the common runtime abstraction interface, implement Java ServiceLoader-based discovery for runtime implementations, create a default no-op implementation for testing, and add unit tests for SPI discovery and core interface contracts, per U3.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A5",
      "activity_name": "Cloud Foundry Runtime SPI Implementation",
      "activity_description": "Develop the Cloud Foundry-specific implementation of the pluggable runtime SPI, including CF app deployment, scaling, route management, and lifecycle management logic, plus integration tests for CF runtime operations, per U3.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A6",
      "activity_name": "On-Prem Kubernetes Runtime SPI Implementation",
      "activity_description": "Develop the on-prem Kubernetes-specific implementation of the pluggable runtime SPI, including Kubernetes deployment, scaling, service management, and lifecycle management logic, plus integration tests for Kubernetes runtime operations, per U3.",
      "most_likely_effort": 32
    },
    {
      "activity_id": "A7",
      "activity_name": "Persistent Stream Metadata Repository Implementation",
      "activity_description": "Design the database schema for stream metadata storage, implement Spring Data JPA repositories for stream definitions and deployment state, add CRUD operation tests, and validate schema compatibility with existing stream models, per U4.",
      "most_likely_effort": 24
    },
    {
      "activity_id": "A8",
      "activity_name": "Stream Failure Recovery Logic Implementation",
      "activity_description": "Develop logic to reestablish streaming pipelines using persisted metadata after failure, including state reconciliation, deployment state recovery, and integration tests for failure recovery scenarios, per U4.",
      "most_likely_effort": 20
    },
    {
      "activity_id": "A9",
      "activity_name": "Sqoop Job Escape Quote Documentation",
      "activity_description": "Create official documentation explaining the escape quote behavior for Sqoop jobs, including examples of double escaping {{\\\\\\\\N}} vs the deprecated {{'\\N'}} format, update the Sqoop job documentation page, and add a migration note for existing users, per U5.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A10",
      "activity_name": "Streaming Pipeline Support for Latest Spark/Spark Streaming Specs",
      "activity_description": "Update Spring XD's streaming pipeline implementation to support the latest Spring for Apache Spark and Spark Structured Streaming APIs, update the stream DSL to align with new specs, and add end-to-end integration tests for pipeline execution with the new Spark versions, per U6.",
      "most_likely_effort": 40
    },
    {
      "activity_id": "A11",
      "activity_name": "Nested Batch Jobs and Workflows Documentation",
      "activity_description": "Create official documentation explaining how to nest batch jobs and workflows in Spring XD, including step-by-step examples, common use cases, best practices, and sample configuration files, per U7.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A12",
      "activity_name": "Import Options Parameterization to Replace —args Option",
      "activity_description": "Refactor all existing Import Job options to be explicitly defined, typed configuration properties bound via Spring @ConfigurationProperties, implement backward compatibility for the existing —args option with deprecation warnings, update all related unit/integration tests, and update documentation for the new parameterized options, per U8.",
      "most_likely_effort": 28
    }
  ],
  "reported_total": {
    "most_likely_effort": 288
  }
}

